import{_ as s,o as e,c as i,a2 as t}from"./chunks/framework.BvlN9b-o.js";const k=JSON.parse('{"title":"创建自己的 SaaS 项目","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/getting-started/create-project","contentType":"guide","prev":{"text":"开发者文档","link":"/docs/"},"next":{"text":"快速开始","link":"/getting-started/quickstart"}},"headers":[],"relativePath":"getting-started/create-project.md","filePath":"getting-started/create-project.md"}'),p={name:"getting-started/create-project.md"};function n(o,a,l,r,h,c){return e(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="创建自己的-saas-项目" tabindex="-1">创建自己的 SaaS 项目 <a class="header-anchor" href="#创建自己的-saas-项目" aria-label="Permalink to &quot;创建自己的 SaaS 项目&quot;">​</a></h1><p>用 Dougong 的脚手架生成完成改名的项目副本，选择是否保留参考应用，并为同机开发分配独立端口。</p><h2 id="_1-创建副本" tabindex="-1">1. 创建副本 <a class="header-anchor" href="#_1-创建副本" aria-label="Permalink to &quot;1. 创建副本&quot;">​</a></h2><p>准备 Node 24.18.0。运行应用还需要 Rust 1.96.0、pnpm 11.17.0、just 1.58.0 和 Docker Compose。</p><p>从 npm 创建项目：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create-axum-saas</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-app</span></span></code></pre></div><p>省略目录参数时会询问项目名。目录末级名称需为小写字母开头的 kebab-case，最长 48 字符；已有目录会被拒绝，文件不会覆盖。默认保留知识库参考应用、便签示例与教学源码。</p><p>也可以从模板仓库根目录构建当前源码快照并使用本地包：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scaffold:pack</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --yes</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --package</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./.scratch/create-package/create-axum-saas-0.1.2.tgz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create-axum-saas</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-app</span></span></code></pre></div><p>打包包含源码快照，创建过程不下载可变的 Git 分支，也不执行依赖安装。生成的副本不带 <code>.git</code>、本机秘密、数据卷或构建目录。</p><h2 id="_2-启动并验证" tabindex="-1">2. 启动并验证 <a class="header-anchor" href="#_2-启动并验证" aria-label="Permalink to &quot;2. 启动并验证&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-app</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frozen-lockfile</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>脚手架把探测可用的端口写入 <code>.env</code>。开发脚本从端口派生连接串、监听地址、代理和浏览器 origin，启动日志显示本副本的 Web、API、Worker 与 Mailpit 地址。打开 Web 的 <code>/register</code>，创建账号后退出，再从 <code>/login</code> 登录。首个账号为 Owner；密码需为 12–128 字符。</p><p>保持开发进程运行，在另一个终端从项目根目录验证：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">project_api</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --input-type=module</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;import { developmentEnv } from &quot;./scripts/lib/process.mjs&quot;; console.log(developmentEnv().APP_BIND)&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;http://</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$project_api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/health/ready&quot;</span></span></code></pre></div><p>预期 HTTP 200，带 <code>x-request-id</code>。<code>Ctrl+C</code> 停止宿主进程；<code>just services-down</code> 停止依赖并保留卷。</p><h2 id="_3-只保留-core" tabindex="-1">3. 只保留 Core <a class="header-anchor" href="#_3-只保留-core" aria-label="Permalink to &quot;3. 只保留 Core&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create-axum-saas</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plain-app</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-examples</span></span></code></pre></div><p><code>--no-examples</code> 去掉全部参考业务与工单教学 fixture，以及示例增删工具、相关编译引用、专属迁移、测试与 CI job；合同和锁文件在打包时已重建。保留身份、企业成员、授权、审计、Jobs、文件、通知与其他共享能力。注册登录后进入通用首页，文档站保留最小双语开发入口和 Core API/配置参考。</p><p>项目名同时用于 npm scope、Rust crates、SQL schema、指标、cookie、浏览器存储键、Electron 桥与本地凭据。可用 <code>--repository owner/repo</code> 设置自己的仓库链接；未设置时生成 <code>your-org/&lt;项目名&gt;</code> 占位，发布文档前应改为真实仓库。许可证归属保持原样。</p><h2 id="_4-同机多副本与失败恢复" tabindex="-1">4. 同机多副本与失败恢复 <a class="header-anchor" href="#_4-同机多副本与失败恢复" aria-label="Permalink to &quot;4. 同机多副本与失败恢复&quot;">​</a></h2><p>创建两份不同目录的副本后，分别安装并运行 <code>just dev</code>。端口预留记录位于用户缓存目录的 <code>create-axum-saas/ports.json</code>，尚未启动的副本也不会被重复分配端口。记录只包含路径和端口，已删除目录的记录会在下次创建时清理。</p><p>开发入口按目录名称和完整路径派生 Compose namespace；同名目录位于不同父目录时也拥有不同容器、卷和网络。旧开发卷保留，不会自动接管。需要显式沿用旧 namespace 时可在进程环境设置 <code>COMPOSE_PROJECT_NAME</code>，并保持端口和凭据一致。</p><p>创建与启动之间端口仍可能被其他进程占用，因此每次启动都重新检查。遇到冲突会列出宿主监听的 PID 或 Docker 容器与项目名，提示停止占用者或修改 <code>.env</code> 中对应的 <code>*_PORT</code>。容器 healthy 但实际绑定缺失时，启动在迁移之前失败。迁移错误会保留 SQLx 的真实原因。</p><p>不要为端口冲突删除卷。下一步阅读<a href="./../architecture/project-structure">项目结构</a>，再<a href="./../guides/new-module">新增业务模块</a>。已生成的 Core 副本可从 <code>crates/app/src/modules</code> 开始自己的业务。</p><h2 id="_5-模板维护者发布-cli" tabindex="-1">5. 模板维护者发布 CLI <a class="header-anchor" href="#_5-模板维护者发布-cli" aria-label="Permalink to &quot;5. 模板维护者发布 CLI&quot;">​</a></h2><p>先修改 <code>tools/create-axum-saas/package.json</code> 的版本并通过 PR 合入 <code>main</code>；npm 已发布的版本不能覆盖。等待该 main 提交的 CI 全部通过。</p><p>仓库 Actions Secret <code>NPM_TOKEN</code> 使用仅授权 <code>create-axum-saas</code> 的 granular token，权限选 <code>Read and write (publish and stage)</code> 并启用 <code>Bypass two-factor authentication</code>。到期后更新 Secret；Actions 发布时不需要交互登录。</p><p>打开 <a href="https://github.com/CaiZongyuan/axum-saas-template/actions/workflows/npm-publish.yml" target="_blank" rel="noreferrer">Publish creator</a>，选择 <code>Run workflow</code>、分支 <code>main</code>，填写与包元数据一致的 <code>version</code>。先保持 <code>publish</code> 不勾选进行预演，查看 npm 身份、包内容和成功结果；再以同样版本勾选 <code>publish</code> 正式发布。正式发布核对版本未被注册、构建默认与 Core 快照，并等待 registry 提供校验值匹配的包。失败时检查版本、Token 权限和有效期；已经发布成功的版本不要重新发布。</p><p><a href="https://docs.npmjs.com/about-access-tokens/" target="_blank" rel="noreferrer">npm 的 token 策略</a>计划在 2027 年 1 月移除 token 直接发布新版本；届时需迁移至 Trusted Publishing 或新的 staging 流程。此维护者 workflow、发布脚本与测试不会进入生成的项目。</p><hr><p>源码版本：<code>261be5bb90df</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/docs/getting-started/create-project.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,32)])])}const g=s(p,[["render",n]]);export{k as __pageData,g as default};
